import json
from itertools import permutations

def solve():
    houses = [1, 2, 3, 4, 5]

    Names = ['Peter', 'Arnold', 'Eric', 'Bob', 'Alice']
    Heights = ['average', 'very tall', 'very short', 'short', 'tall']
    Cigars = ['prince', 'dunhill', 'blends', 'pall mall', 'blue master']
    Smoothies = ['lime', 'cherry', 'dragonfruit', 'watermelon', 'desert']
    Phones = ['oneplus 9', 'samsung galaxy s21', 'iphone 13', 'huawei p50', 'google pixel 6']

    def to_pos_map(by_house):
        # by_house[i] is the item at house i (0-based); return map item -> position (1-based)
        return {item: idx + 1 for idx, item in enumerate(by_house)}

    for names_by_house in permutations(Names):
        pos_name = to_pos_map(names_by_house)

        # Names-only constraints:
        # 2. One house between Eric and Alice.
        if abs(pos_name['Eric'] - pos_name['Alice']) != 2:
            continue
        # 8. Bob is not in the fourth house.
        if pos_name['Bob'] == 4:
            continue
        # 6 + 11 + 14 combined: two houses between very tall (Eric) and dragonfruit (Bob)
        # => |pos(Eric) - pos(Bob)| == 3
        if abs(pos_name['Eric'] - pos_name['Bob']) != 3:
            continue

        for heights_by_house in permutations(Heights):
            pos_height = to_pos_map(heights_by_house)
            # Heights constraints:
            # 6. Eric is very tall.
            if pos_height['very tall'] != pos_name['Eric']:
                continue
            # 17. Arnold and very short are next to each other.
            if abs(pos_name['Arnold'] - pos_height['very short']) != 1:
                continue

            for smoothies_by_house in permutations(Smoothies):
                pos_smoothie = to_pos_map(smoothies_by_house)
                # Smoothies constraints:
                # 11. Dragonfruit lover is Bob.
                if pos_smoothie['dragonfruit'] != pos_name['Bob']:
                    continue
                # 9. Eric is directly left of Cherry.
                if pos_name['Eric'] + 1 != pos_smoothie['cherry']:
                    continue
                # 16. Desert is somewhere to the left of Lime.
                if not (pos_smoothie['desert'] < pos_smoothie['lime']):
                    continue
                # 14. Two houses between very tall and Dragonfruit.
                if abs(pos_height['very tall'] - pos_smoothie['dragonfruit']) != 3:
                    continue

                for cigars_by_house in permutations(Cigars):
                    pos_cigar = to_pos_map(cigars_by_house)
                    # Cigars constraints:
                    # 1. Prince smoker is the Desert smoothie lover.
                    if pos_cigar['prince'] != pos_smoothie['desert']:
                        continue
                    # 10. Bob is the Dunhill smoker.
                    if pos_cigar['dunhill'] != pos_name['Bob']:
                        continue
                    # 5. Average height is the Dunhill smoker.
                    if pos_height['average'] != pos_cigar['dunhill']:
                        continue
                    # 3. Short is Blends smoker.
                    if pos_height['short'] != pos_cigar['blends']:
                        continue
                    # From 4 and 15 together:
                    # 15. iPhone 13 is Eric -> iPhone at pos(Eric)
                    # 4. iPhone is directly left of Blue Master -> Blue Master at pos(Eric)+1
                    if pos_cigar['blue master'] != pos_name['Eric'] + 1:
                        continue

                    for phones_by_house in permutations(Phones):
                        pos_phone = to_pos_map(phones_by_house)
                        # Phones constraints:
                        # 15. iPhone 13 is Eric.
                        if pos_phone['iphone 13'] != pos_name['Eric']:
                            continue
                        # 4. iPhone 13 directly left of Blue Master.
                        if pos_phone['iphone 13'] + 1 != pos_cigar['blue master']:
                            continue
                        # 12. iPhone 13 and OnePlus 9 are next to each other.
                        if abs(pos_phone['iphone 13'] - pos_phone['oneplus 9']) != 1:
                            continue
                        # 7. Arnold is directly left of Huawei P50.
                        if pos_name['Arnold'] + 1 != pos_phone['huawei p50']:
                            continue
                        # 13. Samsung Galaxy S21 user is short.
                        if pos_phone['samsung galaxy s21'] != pos_height['short']:
                            continue

                        # If all constraints passed, we have a solution
                        return names_by_house, heights_by_house, cigars_by_house, smoothies_by_house, phones_by_house

    return None

def main():
    solution = solve()
    if not solution:
        result = {
            "solution": {
                "header": ["House", "Name", "Height", "Cigar", "Smoothie", "PhoneModel"],
                "rows": []
            }
        }
        print(json.dumps(result, indent=2))
        return

    names_by_house, heights_by_house, cigars_by_house, smoothies_by_house, phones_by_house = solution

    rows = []
    for i in range(5):
        house_num = str(i + 1)
        rows.append([
            house_num,
            names_by_house[i],
            heights_by_house[i],
            cigars_by_house[i],
            smoothies_by_house[i],
            phones_by_house[i]
        ])

    result = {
        "solution": {
            "header": ["House", "Name", "Height", "Cigar", "Smoothie", "PhoneModel"],
            "rows": rows
        }
    }
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()
